import com.esf.service.dto.ServiceOrderRequest;
import com.esf.service.dto.ServiceQueryParams;
import com.esf.service.entity.ServiceOrder;
import com.esf.service.service.ServiceOrderService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

@RestController
@RequestMapping("/api/services")
public class ServiceOrderController {

    private final ServiceOrderService serviceOrderService;

    public ServiceOrderController(ServiceOrderService serviceOrderService) {
        this.serviceOrderService = serviceOrderService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<ServiceOrder>> create(@RequestBody ServiceOrderRequest request) {
        ServiceOrder order = serviceOrderService.createOrder(request);
        return ResponseEntity.ok(ApiResponse.success("创建成功", order));
    }

    @GetMapping
    public ResponseEntity<ApiResponse<PageResult<ServiceOrder>>> list(
            @RequestParam(value = "type", required = false) String type,
            @RequestParam(value = "typeValue", required = false) String typeValue,
            @RequestParam(value = "orgId", required = false) String orgId,
            @RequestParam(value = "departmentId", required = false) String departmentId,
            @RequestParam(value = "skillGroupId", required = false) String skillGroupId,
            @RequestParam(value = "status", required = false) String status,
            @RequestParam(value = "current", required = false) Integer current,
            @RequestParam(value = "size", required = false) Integer size) {
        ServiceQueryParams params = new ServiceQueryParams();
        params.setType(type);
        params.setTypeValue(typeValue);
        params.setOrgId(orgId);
        params.setDepartmentId(departmentId);
        params.setSkillGroupId(skillGroupId);
        params.setStatus(status);
        if (current != null) {
            params.setCurrent(current);
        }
        if (size != null) {
            params.setSize(size);
        }
        PageResult<ServiceOrder> page = serviceOrderService.queryOrders(params);
        return ResponseEntity.ok(ApiResponse.success("查询成功", page));
    }

    @GetMapping("/stats")
    public ResponseEntity<ApiResponse<Map<String, Long>>> stats(
            @RequestParam(value = "orgId", required = false) String orgId) {
        return ResponseEntity.ok(ApiResponse.success("查询成功", serviceOrderService.getStats(orgId)));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<ServiceOrder>> detail(@PathVariable("id") Long id) {
        ServiceOrder order = serviceOrderService.getById(id);
        if (order == null) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.error(404, "工单不存在"));
        }
        return ResponseEntity.ok(ApiResponse.success("查询成功", order));
    }

    @PutMapping("/{id}/status")
    public ResponseEntity<ApiResponse<Map<String, Object>>> updateStatus(
            @PathVariable("id") Long id, @RequestBody Map<String, String> body) {
        Map<String, Object> result = serviceOrderService.updateStatus(id, body.get("status"), body.get("owner"));
        if (result == null) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.error(404, "工单不存在"));
        }
        return ResponseEntity.ok(ApiResponse.success("更新成功", result));
    }
}

package com.esf.service.dto;

public class ApiResponse<T> {

    private int code;
    private String message;
    private T data;

    public ApiResponse() {
    }

    public ApiResponse(int code, String message, T data) {
        this.code = code;
        this.message = message;
        this.data = data;
    }

    public static <T> ApiResponse<T> success(String message, T data) {
        return new ApiResponse<>(200, message, data);
    }

    public static <T> ApiResponse<T> error(int code, String message) {
        return new ApiResponse<>(code, message, null);
    }

    public int getCode() {
        return code;
    }

    public void setCode(int code) {
        this.code = code;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public T getData() {
        return data;
    }

    public void setData(T data) {
        this.data = data;
    }
}

